function errorText(error:unknown){return error&&typeof error==='object'&&'message'in error?String((error as {message:unknown}).message):'The request could not be completed. Please try again.'}
function safeSearch(value:string){return value.trim().replace(/[%,()_*]/g,' ').replace(/\s+/g,' ').slice(0,80)}
function useLoad<T>(loader:()=>Promise<T>){const [data,setData]=useState<T|null>(null),[error,setError]=useState(''),[loading,setLoading]=useState(true),[reload,setReload]=useState(0);const refresh=useCallback(()=>setReload(x=>x+1),[]);useEffect(()=>{let live=true;setLoading(true);setError('');setData(null);void loader().then(value=>{if(live)setData(value)}).catch(e=>{if(live)setError(errorText(e))}).finally(()=>{if(live)setLoading(false)});return()=>{live=false}},[reload,loader]);return {data,error,loading,refresh}}
function PageState({loading,error,empty,children}:{loading:boolean,error:string,empty?:string,children?:React.ReactNode}){if(loading)return <div className="panel feature-state" role="status">Loading CityCare data…</div>;if(error)return <div className="setup-note feature-error">{error}</div>;if(empty)return <div className="panel feature-state">{empty}</div>;return <>{children}</>}
function Title({title,description,action}:{title:string,description:string,action?:React.ReactNode}){return <div className="feature-heading"><div><span className="eyebrow">CITYCARE WORKSPACE</span><h1>{title}<span>.</span></h1><p>{description}</p></div>{action}</div>}
function Button({children,onClick,disabled=false}:{children:React.ReactNode,onClick?:()=>void,disabled?:boolean}){return <button type="button" className="btn outline" onClick={onClick} disabled={disabled}>{children}</button>}
function Status({value}:{value:string}){return <span className={`status ${value.toLowerCase().replaceAll(' ','-')}`}><i/>{value}</span>}
async function fetchAllRows(client:Client,table:string,columns:string,orderColumn?:string){const rows:any[]=[];for(let start=0;;start+=1000){let query=client.from(table).select(columns);if(orderColumn)query=query.order(orderColumn,{ascending:false});const {data,error}=await query.range(start,start+999);if(error)throw error;const page=data??[];rows.push(...page);if(page.length<1000)break}return rows}
type WorkEvidence={id:string,complaint_id:string,worker_id:string,evidence_type:string,storage_path:string,remarks:string|null,created_at:string,signedUrl:string|null,workerName:string}
const evidenceBucket='work-evidence'
const maxEvidenceBytes=10*1024*1024
const allowedEvidenceTypes=new Set(['image/jpeg','image/png','image/webp'])
