function useComplaintRows(client:Client){const loader=useCallback(async()=>{const rows=await fetchAllRows(client,'complaints','id,complaint_number,description,category_id,latitude,longitude,location_description,zone_id,priority,status,submitted_at,updated_at,resolved_at,deadline,rejection_reason,admin_remarks,issue_categories(name),administrative_zones(name),profiles!complaints_citizen_id_fkey(full_name,email,phone)','submitted_at');return rows as Complaint[]},[client]);const result=useLoad(loader);useEffect(()=>{const channel=client.channel('workspace-complaint-data').on('postgres_changes',{event:'*',schema:'public',table:'complaints'},result.refresh).subscribe();return()=>{void client.removeChannel(channel)}},[client,result.refresh]);return result}

