 const allowed=data?role==='admin'?({Reported:['Under Review','Rejected'],'Under Review':['Verified','Rejected'],Verified:[],Assigned:[], 'In Progress':[], 'Resolution Submitted':['Resolved','In Progress']} as Record<string,string[]>)[data.status]??[]:role==='worker'&&data.status==='Assigned'?['In Progress']:role==='worker'&&data.status==='In Progress'?['Resolution Submitted']:[]:[]
 const save=async()=>{if(!nextStatus)return;setBusy(true);setMessage('');try{const patch:any={status:nextStatus,updated_at:new Date().toISOString()};if(role==='admin'&&remarks)patch.admin_remarks=remarks;if(nextStatus==='Rejected'&&!remarks.trim())throw new Error('A rejection reason is required.');if(nextStatus==='Rejected')patch.rejection_reason=remarks.trim();if(nextStatus==='Resolved')patch.resolved_at=new Date().toISOString();const {error}=await client.from('complaints').update(patch).eq('id',id);if(error)throw error;let assignmentWarning='';if(nextStatus==='In Progress'){let assignedWorkerId='';if(role==='worker'){const {data:{user}}=await client.auth.getUser();if(user){const {data:worker}=await client.from('workers').select('id').eq('profile_id',user.id).maybeSingle();assignedWorkerId=worker?.id??''}}else if(role==='admin'&&data.status==='Resolution Submitted'){const {data:evidenceRow}=await client.from('work_evidence').select('worker_id').eq('complaint_id',id).order('created_at',{ascending:false}).limit(1).maybeSingle();assignedWorkerId=evidenceRow?.worker_id??''}if(assignedWorkerId){const {error:assignmentTransitionError}=await client.from('worker_assignments').update({assignment_status:'in_progress'}).eq('complaint_id',id).eq('worker_id',assignedWorkerId).in('assignment_status',role==='admin'?['submitted']:['assigned','accepted']);if(assignmentTransitionError)assignmentWarning=` Complaint status was saved, but assignment status could not be advanced: ${errorText(assignmentTransitionError)}`}}if(role==='worker'&&remarks.trim()){const {data:{user}}=await client.auth.getUser();if(user)await client.from('complaint_updates').insert({complaint_id:id,actor_id:user.id,remarks:remarks.trim()})}setMessage(assignmentWarning||'Complaint status updated.');setRemarks('');setNextStatus('');refresh()}catch(e){setMessage(errorText(e))}finally{setBusy(false)}}
