 const assignmentRows=source.assignments.filter(a=>complaints.some(c=>c.id===a.complaint_id)&&assignmentStatuses.includes(a.assignment_status))
 const workerAgg=new Map<string,{workerId:string,name:string,assigned:number,completed:number,inProgress:number,overdue:number,completionDays:number[]}>()
 for(const assignment of assignmentRows){const workerId=assignment.worker_id,name=workerMap.get(workerId)||workerId;const item:{workerId:string,name:string,assigned:number,completed:number,inProgress:number,overdue:number,completionDays:number[]}=workerAgg.get(workerId)??{workerId,name,assigned:0,completed:0,inProgress:0,overdue:0,completionDays:[]};if(assignment.assignment_status!=='reassigned')item.assigned++;if(assignment.assignment_status==='completed'){item.completed++;const resolvedAt=complaintById.get(assignment.complaint_id)?.resolved_at;if(resolvedAt&&assignment.assigned_at)item.completionDays.push(Math.max(0,(new Date(resolvedAt).getTime()-new Date(assignment.assigned_at).getTime())/86400000))}if(assignment.assignment_status==='in_progress')item.inProgress++;if(['assigned','accepted','in_progress','submitted'].includes(assignment.assignment_status)&&assignment.deadline&&new Date(assignment.deadline)<new Date())item.overdue++;workerAgg.set(workerId,item)}
 const workerData=[...workerAgg.values()].map(w=>({...w,averageDays:w.completionDays.length?w.completionDays.reduce((a,b)=>a+b,0)/w.completionDays.length:null})).sort((a,b)=>b.assigned-a.assigned)
 const catAgg=new Map<string,{id:string,name:string,total:number,resolved:number,pending:number}>()
 for(const c of complaints){const id=c.category_id||'unknown',name=categoryMap.get(id)||'Unknown category',item=catAgg.get(id)??{id,name,total:0,resolved:0,pending:0};item.total++;if(c.status==='Resolved')item.resolved++;if(pendingComplaintStatuses.includes(c.status))item.pending++;catAgg.set(id,item)}
 const categoryData=[...catAgg.values()].map(c=>({...c,resolutionRate:c.total?c.resolved/c.total*100:0,color:categoryColor(c.id)})).sort((a,b)=>b.total-a.total)
 const zoneAgg=new Map<string,{id:string,name:string,total:number,resolved:number,highPriority:number}>()
 for(const c of complaints){const id=c.zone_id||'unassigned',name=zoneMap.get(id)||'Unassigned',item=zoneAgg.get(id)??{id,name,total:0,resolved:0,highPriority:0};item.total++;if(c.status==='Resolved')item.resolved++;if(['High','Urgent'].includes(c.priority))item.highPriority++;zoneAgg.set(id,item)}
