export function GlobalSearch({client,role,onNavigate}:{client:Client,role:Role,onNavigate:(path:string)=>void}){
 const [open,setOpen]=useState(false),[query,setQuery]=useState(''),[results,setResults]=useState<Result[]>([]),[loading,setLoading]=useState(false),[error,setError]=useState('')
 useEffect(()=>{if(!open||safeSearch(query).length<2){setResults([]);setError('');return}const term=safeSearch(query);let live=true;const timer=window.setTimeout(()=>{void(async()=>{setLoading(true);setError('');const pattern=`%${term}%`;try{const tasks:any[]=[client.from('complaints').select('id,complaint_number,description,status,location_description').ilike('description',pattern).limit(8)];if(role==='admin')tasks.push(client.from('issue_categories').select('id,name').ilike('name',pattern).limit(5));if(role==='admin')tasks.push(client.from('profiles').select('id,full_name,email,role').eq('role','worker').ilike('full_name',pattern).limit(5),client.from('administrative_zones').select('id,name').ilike('name',pattern).limit(5));if(/^\d+$/.test(term))tasks.push(client.from('complaints').select('id,complaint_number,description,status,location_description').eq('complaint_number',Number(term)).limit(5));const responses=await Promise.all(tasks);const failed=responses.find(r=>r.error);if(failed)throw failed.error;const out:Result[]=[];for(const c of responses[0].data??[])out.push({kind:'complaint',id:c.id,label:`CC-${c.complaint_number}`,detail:`${c.status} · ${c.description}`,path:role==='admin'?'complaints':role==='worker'?'my-tasks':'my-complaints'});for(const c of (role==='admin'?responses[1]?.data??[]:[]))out.push({kind:'category',id:String(c.id),label:c.name,detail:'Complaint category',path:role==='admin'?'categories':'my-complaints'});if(role==='admin'){for(const w of responses[2]?.data??[])out.push({kind:'worker',id:w.id,label:w.full_name,detail:w.email,path:'workers'});for(const z of responses[3]?.data??[])out.push({kind:'zone',id:z.id,label:z.name,detail:'Administrative zone',path:'zones'})}if(/^\d+$/.test(term)){const exact=responses.at(-1)?.data??[];for(const c of exact)if(!out.some(x=>x.id===c.id))out.unshift({kind:'complaint',id:c.id,label:`CC-${c.complaint_number}`,detail:`${c.status} · ${c.description}`,path:role==='admin'?'complaints':role==='worker'?'my-tasks':'my-complaints'})}if(live)setResults(out)}catch(e){if(live)setError(errorText(e))}finally{if(live)setLoading(false)}})()},300);return()=>{live=false;window.clearTimeout(timer)}},[client,open,query,role])
 const select=(result:Result)=>{setOpen(false);setQuery('');onNavigate(`/${role}/${result.path}${result.kind==='complaint'?`?complaint=${encodeURIComponent(result.id)}`:''}`)}
 return <div className="feature-popover-anchor"><button className="icon-btn" aria-label="Search" aria-expanded={open} onClick={()=>setOpen(x=>!x)}><Search size={18}/></button>{open&&<section className="feature-popover feature-search"><div className="feature-popover-head"><b>Search CityCare</b><button onClick={()=>setOpen(false)} aria-label="Close search"><X size={16}/></button></div><input autoFocus style={fieldStyle} placeholder="Complaint number, description, category…" value={query} onChange={e=>setQuery(e.target.value)}/><div className="feature-search-results">{query.trim().length<2?<p className="muted">Enter at least two characters.</p>:loading?<p className="muted">Searching…</p>:error?<p className="feature-message">{error}</p>:results.length?results.map((r,i)=><button key={`${r.kind}-${r.id}-${i}`} onClick={()=>select(r)}><b>{r.label}</b><small>{r.detail}</small><ExternalLink size={13}/></button>):<p className="muted">No matching records.</p>}</div></section>}</div>
}

export function ProfileMenu({client,user,role,onLogout,alwaysOpen=false}:{client:Client,user:User|null,role:Role,onLogout:()=>void,alwaysOpen?:boolean}){
 const [open,setOpen]=useState(false),[editing,setEditing]=useState(false),[changingPassword,setChangingPassword]=useState(false),[profile,setProfile]=useState<any>(null),[name,setName]=useState(''),[phone,setPhone]=useState(''),[password,setPassword]=useState(''),[message,setMessage]=useState(''),[busy,setBusy]=useState(false),[roleActivity,setRoleActivity]=useState(''),[recentActivity,setRecentActivity]=useState<any[]>([])
 const visible=alwaysOpen||open
 useEffect(()=>{let live=true;void(async()=>{if(!user)return;const {data}=await client.from('profiles').select('id,full_name,email,phone,role,created_at').eq('id',user.id).maybeSingle();if(live&&data){const record=data;setProfile(record);setName(record.full_name??'');setPhone(record.phone??'');let activityCount=0;let activityLabel='';const activityResult=role==='citizen'?await client.from('complaints').select('id',{count:'exact',head:true}).eq('citizen_id',user.id):role==='worker'?await (async()=>{const {data:worker}=await client.from('workers').select('id').eq('profile_id',user.id).maybeSingle();return worker?client.from('worker_assignments').select('id',{count:'exact',head:true}).eq('worker_id',worker.id).in('assignment_status',['assigned','accepted','in_progress']):{count:0}})():await client.from('complaints').select('id',{count:'exact',head:true});activityCount=activityResult.count??0;activityLabel=role==='citizen'?'submitted complaints':role==='worker'?'active assignments':'complaints visible to admins';setRoleActivity(`${activityCount} ${activityLabel}`);const history=await client.from('complaint_updates').select('id,new_status,remarks,created_at').order('created_at',{ascending:false}).limit(3);setRecentActivity(history.data??[])}})();return()=>{live=false}},[client,user?.id,visible])
 const saveProfile=async()=>{if(!user)return;setBusy(true);setMessage('');const {error}=await client.from('profiles').update({full_name:name.trim(),phone:phone.trim()||null}).eq('id',user.id);if(error)setMessage(errorText(error));else{setMessage('Profile updated.');setEditing(false);setProfile((p:any)=>({...p,full_name:name.trim(),phone:phone.trim()||null}))}setBusy(false)}
 const savePassword=async()=>{if(password.length<8){setMessage('Use at least 8 characters for your new password.');return}setBusy(true);const {error}=await client.auth.updateUser({password});setPassword('');setMessage(error?errorText(error):'Password changed.');setBusy(false);if(!error)setChangingPassword(false)}
 const roleInfo=role==='admin'?'City operations administrator':role==='worker'?'Field operations worker':'Citizen services account'
 return <div className={`feature-popover-anchor ${alwaysOpen?'feature-profile-anchor-page':''}`}>{!alwaysOpen&&<button className="avatar small feature-profile-button" aria-label="Profile menu" aria-expanded={open} onClick={()=>setOpen(x=>!x)}>{(profile?.full_name??user?.email??'U').slice(0,2).toUpperCase()}</button>}{visible&&<section className={`feature-popover feature-profile ${alwaysOpen?'feature-profile-page':''}`}><div className="feature-popover-head"><b>My profile</b><button onClick={()=>setOpen(false)} aria-label="Close profile"><X size={16}/></button></div>{profile?<><div className="feature-profile-summary"><b>{profile.full_name||'Unnamed user'}</b><small>{profile.email||user?.email}</small><small>{role[0].toUpperCase()+role.slice(1)} · {roleInfo}</small></div>{editing?<><label>Full name<input style={fieldStyle} value={name} onChange={e=>setName(e.target.value)}/></label><label>Phone<input style={fieldStyle} value={phone} onChange={e=>setPhone(e.target.value)}/></label><button className="btn primary" disabled={busy} onClick={()=>void saveProfile()}>Save profile</button></>:<><dl className="feature-profile-details"><dt>Phone</dt><dd>{profile.phone||'Not provided'}</dd><dt>Role</dt><dd>{profile.role}</dd><dt>Account status</dt><dd>{'Not tracked in current profiles schema'}</dd><dt>Created</dt><dd>{profile.created_at?new Date(profile.created_at).toLocaleDateString():'Not available'}</dd><dt>User ID</dt><dd className="feature-id">{profile.id}</dd><dt>Role activity</dt><dd>{roleActivity||'Not available'}</dd></dl>{recentActivity.length>0&&<div className="feature-recent-activity"><b>Recent activity</b>{recentActivity.map(a=><small key={a.id}>{a.new_status||a.remarks||'Complaint update'} · {new Date(a.created_at).toLocaleString()}</small>)}</div>}<button className="btn outline" onClick={()=>setEditing(true)}>Edit profile</button></>}{changingPassword?<div className="feature-password"><label>New password<input style={fieldStyle} type="password" autoComplete="new-password" value={password} onChange={e=>setPassword(e.target.value)}/></label><button className="btn outline" disabled={busy} onClick={()=>void savePassword()}>Save password</button></div>:<button className="btn outline" onClick={()=>setChangingPassword(true)}>Change password</button>}{message&&<p className="feature-message" role="status">{message}</p>}</>:<p className="muted">Profile details are not available.</p>}<hr/><button className="btn outline" onClick={onLogout}>Log out</button></section>}</div>
}
